function generateBase(){normalizeState();typeLimited=false;paths=[];dims=pageDimensions();preparePoster();const [w,h]=dims,m=s.margin,p=s.params,r=random(s.seed),n=noiseFactory(s.seed),colors=palette().length;
if(s.engine==='flow'){const centers=[{x:w*.43,y:h*.44},{x:w*.68,y:h*.65}],fb=(x,y)=>{let v=0,a=1,sum=0;for(let i=0;i<p.octaves;i++){v+=n(x,y)*a;sum+=a;a*=.5;x*=2;y*=2}return v/sum};for(let i=0;i<p.density;i++){let source=posterSource(r),x=source?source[0]:m+r()*(w-2*m),y=source?source[1]:m+r()*(h-2*m),pts=[];for(let j=0;j<p.length;j++){pts.push([x,y]);let angle=fb(x/w*p.frequency+phase*.15,y/h*p.frequency)*Math.PI*p.amplitude+.35;let vx=Math.cos(angle),vy=Math.sin(angle);let ctr=s.points.length?s.points:centers;for(let c of ctr){let dx=x-c.x,dy=y-c.y,d=Math.hypot(dx,dy)+.1,k=p.force*Math.exp(-d/(w*.28));if(p.field==='vortex'){vx+=-dy/d*k;vy+=dx/d*k}else{vx-=dx/d*k;vy-=dy/d*k}}if(s.poster.enabled&&s.poster.effect==='repel'){const f=textForce(x,y);vx+=f[0]*s.poster.strength;vy+=f[1]*s.poster.strength}if(source&&j<12){const a=(i%2?1:-1)*Math.PI/2;vx+=Math.cos(a)*(1-j/12)*2;vy+=Math.sin(a)*(1-j/12)*2}let norm=Math.hypot(vx,vy)||1;x+=vx/norm*.75;y+=vy/norm*.75;if(x<m||x>w-m||y<m||y>h-m)break}add(pts,i%colors)}}
if(s.engine==='cell'){let sites=Array.from({length:p.density},()=>[m+r()*(w-2*m),m+r()*(h-2*m)]),edges=new Set;sites.forEach((a,i)=>{let poly=[[m,m],[w-m,m],[w-m,h-m],[m,h-m]];sites.forEach((b,j)=>{if(i===j)return;let dx=b[0]-a[0],dy=b[1]-a[1],limit=(b[0]*b[0]+b[1]*b[1]-a[0]*a[0]-a[1]*a[1])/2,out=[];for(let k=0;k<poly.length;k++){let u=poly[k],v=poly[(k+1)%poly.length],du=u[0]*dx+u[1]*dy-limit,dv=v[0]*dx+v[1]*dy-limit;if(du<=0)out.push(u);if((du<0)!==(dv<0)){let t=du/(du-dv);out.push([u[0]+(v[0]-u[0])*t,u[1]+(v[1]-u[1])*t])}}poly=out});if(!poly.length)return;if(p.mode==='delaunay'){for(let k=0;k<poly.length;k++){let u=poly[k],v=poly[(k+1)%poly.length],mid=[(u[0]+v[0])/2,(u[1]+v[1])/2];for(let j=i+1;j<sites.length;j++){let b=sites[j];if(Math.abs(Math.hypot(mid[0]-a[0],mid[1]-a[1])-Math.hypot(mid[0]-b[0],mid[1]-b[1]))<.001)edges.add(i+','+j)}}}else{let cx=poly.reduce((t,v)=>t+v[0],0)/poly.length,cy=poly.reduce((t,v)=>t+v[1],0)/poly.length,dx=cx-w/2,dy=cy-h/2,dist=Math.hypot(dx,dy)||1,ex=p.explode*(.5+.5*n(cx*.02,cy*.02));let pts=poly.map(v=>[cx+(v[0]-cx)*(1-p.offset/100)+dx/dist*ex,cy+(v[1]-cy)*(1-p.offset/100)+dy/dist*ex]);add([...pts,pts[0]],i%colors)}});if(p.mode==='delaunay')for(let e of edges){let[i,j]=e.split(',').map(Number);const transform=a=>{let dx=a[0]-w/2,dy=a[1]-h/2,d=Math.hypot(dx,dy)||1,k=p.explode*(.5+.5*n(a[0]*.02,a[1]*.02));return[a[0]+dx/d*k,a[1]+dy/d*k]};let a=transform(sites[i]),b=transform(sites[j]),t=p.offset/200;add([[a[0]+(b[0]-a[0])*t,a[1]+(b[1]-a[1])*t],[b[0]+(a[0]-b[0])*t,b[1]+(a[1]-b[1])*t]],i%colors)}}
if(s.engine==='op'){for(let i=0;i<p.density;i++){let pts=[],t=i/(p.density-1);for(let j=0;j<=260;j++){let u=j/260;if(p.mode==='rings'){let a=u*Math.PI*2,rad=3+t*Math.min(w,h)*.57,warp=Math.sin(a*p.frequency+phase+t*8)*p.amplitude*t*.35;pts.push([w/2+Math.cos(a)*(rad+warp),h/2+Math.sin(a)*(rad+warp)])}else{let x=m+u*(w-2*m),y=m+t*(h-2*m)+Math.sin(u*Math.PI*p.frequency+phase+t*4)*p.amplitude*Math.sin(Math.PI*t);pts.push([x,y])}}add(pts,i%colors)}}
if(s.engine==='type')generateType(p,n,colors);
if(s.engine==='super')generateSuper(p,colors);
if(s.engine==='iso')generateIso(p,colors);
applyPoster();
return paths}
